window.NCERT_CLOZE_DATA["Biodiversity_and_Conservation"] = {"id": "Biodiversity_and_Conservation", "title": "Biodiversity and Conservation", "subject": "Botany", "class": "Class 12", "chapter_no": 15, "stats": {"sentences": 187, "blanks": 141, "skipped_sentences": 92, "elements": 200}, "elements": [{"type": "h4", "content": "Chapter 15"}, {"type": "h2", "content": "BIODIVERSITY AND CONSERVATION"}, {"type": "h2", "content": "15.1 Biodiversity 15.2 Biodiversity Conservation"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s1", "tokens": [{"t": "text", "v": "15.1 Biodiversity"}], "blanks": [], "text": "15.1 Biodiversity"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s2", "tokens": [{"t": "text", "v": "15.2 Biodiversity Conservation"}], "blanks": [], "text": "15.2 Biodiversity Conservation"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s3", "tokens": [{"t": "text", "v": "If an alien from a distant galaxy were to visit our planet Earth, the first thing that would amaze and baffle him would most probably be the enormous diversity of life that he would encounter."}], "blanks": [], "text": "If an alien from a distant galaxy were to visit our planet Earth, the first thing that would amaze and baffle him would most probably be the enormous diversity of life that he would encounter."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s4", "tokens": [{"t": "text", "v": "Even for humans, the rich variety of living organisms with which they share this planet never ceases to astonish and fascinate us."}], "blanks": [], "text": "Even for humans, the rich variety of living organisms with which they share this planet never ceases to astonish and fascinate us."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s5", "tokens": [{"t": "text", "v": "The common man would find it hard to believe that there are more than "}, {"t": "cloze", "v": "20,000 species of ants"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "3,00,000 species of beetles"}, {"t": "text", "v": ", 28,000 species of fishes and nearly 20,000 species of orchids."}], "blanks": ["20,000 species of ants", "3,00,000 species of beetles"], "text": "The common man would find it hard to believe that there are more than 20,000 species of ants, 3,00,000 species of beetles, 28,000 species of fishes and nearly 20,000 species of orchids."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s6", "tokens": [{"t": "text", "v": "Ecologists and evolutionary biologists have been trying to understand the significance of such diversity by asking important questions– Why are there so many species?"}], "blanks": [], "text": "Ecologists and evolutionary biologists have been trying to understand the significance of such diversity by asking important questions– Why are there so many species?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s7", "tokens": [{"t": "text", "v": "Did such great diversity exist throughout earth’s history?"}], "blanks": [], "text": "Did such great diversity exist throughout earth’s history?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s8", "tokens": [{"t": "text", "v": "How did this diversification come about?"}], "blanks": [], "text": "How did this diversification come about?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s9", "tokens": [{"t": "text", "v": "How and why is this diversity important to the biosphere?"}], "blanks": [], "text": "How and why is this diversity important to the biosphere?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s10", "tokens": [{"t": "text", "v": "Would it function any differently if the diversity was much less?"}], "blanks": [], "text": "Would it function any differently if the diversity was much less?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s11", "tokens": [{"t": "text", "v": "How do humans benefit from the diversity of life?"}], "blanks": [], "text": "How do humans benefit from the diversity of life?"}, {"type": "h2", "content": "15.1 Biodiversity"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s12", "tokens": [{"t": "text", "v": "In our biosphere immense diversity (or heterogeneity) exists not only at the species level but at all levels of biological organisation ranging from macromolecules within cells to biomes."}], "blanks": [], "text": "In our biosphere immense diversity (or heterogeneity) exists not only at the species level but at all levels of biological organisation ranging from macromolecules within cells to biomes."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s13", "tokens": [{"t": "text", "v": "Biodiversity is the term popularised by the sociob iologist "}, {"t": "cloze", "v": "Edward Wilson"}, {"t": "text", "v": " to describe the combined diversity at all the levels of biological organisation."}], "blanks": ["Edward Wilson"], "text": "Biodiversity is the term popularised by the sociob iologist Edward Wilson to describe the combined diversity at all the levels of biological organisation."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s14", "tokens": [{"t": "text", "v": "The most important of them are–"}], "blanks": [], "text": "The most important of them are–"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s15", "tokens": [{"t": "text", "v": "(i) "}, {"t": "cloze", "v": "Genetic diversit y"}, {"t": "text", "v": " : A single species might show high diversity at the genetic level over its distributional range."}], "blanks": ["Genetic diversit y"], "text": "(i) Genetic diversit y : A single species might show high diversity at the genetic level over its distributional range."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s16", "tokens": [{"t": "text", "v": "The genetic variation shown by the medicinal plant "}, {"t": "cloze", "v": "Rauwolfia vomitoria"}, {"t": "text", "v": " growing in different Himalayan ranges might be in terms of the potency and concentration of the active chemical ("}, {"t": "cloze", "v": "reserpine"}, {"t": "text", "v": ") that the plant produces."}], "blanks": ["Rauwolfia vomitoria", "reserpine"], "text": "The genetic variation shown by the medicinal plant Rauwolfia vomitoria growing in different Himalayan ranges might be in terms of the potency and concentration of the active chemical (reserpine) that the plant produces."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s17", "tokens": [{"t": "text", "v": "India has more than "}, {"t": "cloze", "v": "50,000 genetically different strains of rice"}, {"t": "text", "v": ", and "}, {"t": "cloze", "v": "1,000 varieties of mango"}, {"t": "text", "v": "."}], "blanks": ["50,000 genetically different strains of rice", "1,000 varieties of mango"], "text": "India has more than 50,000 genetically different strains of rice, and 1,000 varieties of mango."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s18", "tokens": [{"t": "text", "v": "(ii) Species diversity : The diversity at the species level, for example, the "}, {"t": "cloze", "v": "Western Ghats"}, {"t": "text", "v": " have a greater amphibian species diversity than the "}, {"t": "cloze", "v": "Eastern Ghats"}, {"t": "text", "v": "."}], "blanks": ["Western Ghats", "Eastern Ghats"], "text": "(ii) Species diversity : The diversity at the species level, for example, the Western Ghats have a greater amphibian species diversity than the Eastern Ghats."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s19", "tokens": [{"t": "text", "v": "(iii) Ecological diversity : At the ecosystem level, India, for instance, with its deserts, rain forests, mangroves, coral reefs, wetlands, estuaries, and alpine meadows has a greater ecosystem diversity than a Scandinavian country like Norway."}], "blanks": [], "text": "(iii) Ecological diversity : At the ecosystem level, India, for instance, with its deserts, rain forests, mangroves, coral reefs, wetlands, estuaries, and alpine meadows has a greater ecosystem diversity than a Scandinavian country like Norway."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s20", "tokens": [{"t": "text", "v": "It has taken millions of years of evolution, to accumulate this rich diversity in nature, but we could lose all that wealth in less than two centuries if the present rates of species losses continue."}], "blanks": [], "text": "It has taken millions of years of evolution, to accumulate this rich diversity in nature, but we could lose all that wealth in less than two centuries if the present rates of species losses continue."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s21", "tokens": [{"t": "text", "v": "Biodiversity and its conservation are now vital environmental issues of international concern as more and more people around the world begin to realise the critical importance of biodiversity for our survival and well- being on this planet."}], "blanks": [], "text": "Biodiversity and its conservation are now vital environmental issues of international concern as more and more people around the world begin to realise the critical importance of biodiversity for our survival and well- being on this planet."}, {"type": "h3", "content": "15.1.1 How Many Species are there on Earth and How Many in India?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s22", "tokens": [{"t": "text", "v": "Si nce there are published records of all the species discovered and named, we know how many species in all have been recorded so far, but it is not easy to answer the question of how many species there are on earth."}], "blanks": [], "text": "Si nce there are published records of all the species discovered and named, we know how many species in all have been recorded so far, but it is not easy to answer the question of how many species there are on earth."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s23", "tokens": [{"t": "text", "v": "According to the "}, {"t": "cloze", "v": "International Union for Conservation of Nature and Natural Resources (IUCN)"}, {"t": "text", "v": " (2004), the total number of plant and animal species described so far is slightly more than "}, {"t": "cloze", "v": "1.5 million"}, {"t": "text", "v": ", but we have no clear idea of how many species are yet to be discovered and described."}], "blanks": ["International Union for Conservation of Nature and Natural Resources (IUCN)", "1.5 million"], "text": "According to the International Union for Conservation of Nature and Natural Resources (IUCN) (2004), the total number of plant and animal species described so far is slightly more than 1.5 million, but we have no clear idea of how many species are yet to be discovered and described."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s24", "tokens": [{"t": "text", "v": "Estimates vary widely and many of them are only educated guesses."}], "blanks": [], "text": "Estimates vary widely and many of them are only educated guesses."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s25", "tokens": [{"t": "text", "v": "For many taxonomic groups, species inventories are more complete in temperate than in tropical countries."}], "blanks": [], "text": "For many taxonomic groups, species inventories are more complete in temperate than in tropical countries."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s26", "tokens": [{"t": "text", "v": "Considering that an overwhelmingly large proportion of the species waiting to be discovered are in the tropics, biologists make a statistical comparison of the temperate-tropical species richness of an exhaustively studied group of insects and extrapolate this ratio to other groups of animals and plants to come up with a gross estimate of the total number of species on earth."}], "blanks": [], "text": "Considering that an overwhelmingly large proportion of the species waiting to be discovered are in the tropics, biologists make a statistical comparison of the temperate-tropical species richness of an exhaustively studied group of insects and extrapolate this ratio to other groups of animals and plants to come up with a gross estimate of the total number of species on earth."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s27", "tokens": [{"t": "text", "v": "Some extreme estimates range from 20 to 50 million, but a more conservative and scientifically sound estimate made by "}, {"t": "cloze", "v": "Robert May"}, {"t": "text", "v": " places the global species diversity at about "}, {"t": "cloze", "v": "7 million"}, {"t": "text", "v": "."}], "blanks": ["Robert May", "7 million"], "text": "Some extreme estimates range from 20 to 50 million, but a more conservative and scientifically sound estimate made by Robert May places the global species diversity at about 7 million."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s28", "tokens": [{"t": "text", "v": "Let us look at so me interesting aspects about earth’s biodiversity based on the currently available species inventories."}], "blanks": [], "text": "Let us look at so me interesting aspects about earth’s biodiversity based on the currently available species inventories."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s29", "tokens": [{"t": "text", "v": "More than "}, {"t": "cloze", "v": "70 per cent"}, {"t": "text", "v": " of all the species recorded are animals, while plants (including algae, fungi, bryophytes, gymnosperms and angiosperms) comprise no more than 22 per cent of the total. Among animals, "}, {"t": "cloze", "v": "insects"}, {"t": "text", "v": " are the most species-rich taxonomic group, making up more than "}, {"t": "cloze", "v": "70 per cent"}, {"t": "text", "v": " of the total. That means, out of every 10 animals on this planet, 7 are "}, {"t": "cloze", "v": "insects"}, {"t": "text", "v": "."}], "blanks": ["70 per cent", "insects", "70 per cent", "insects"], "text": "More than 70 per cent of all the species recorded are animals, while plants (including algae, fungi, bryophytes, gymnosperms and angiosperms) comprise no more than 22 per cent of the total. Among animals, insects are the most species-rich taxonomic group, making up more than 70 per cent of the total. That means, out of every 10 animals on this planet, 7 are insects."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s30", "tokens": [{"t": "text", "v": "Again, how do we explain this enormous diversification of insects?"}], "blanks": [], "text": "Again, how do we explain this enormous diversification of insects?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s31", "tokens": [{"t": "text", "v": "The number of "}, {"t": "cloze", "v": "fungi"}, {"t": "text", "v": " species in the world is more than the combined total of the species of fishes, amphibians, reptiles and mammals."}], "blanks": ["fungi"], "text": "The number of fungi species in the world is more than the combined total of the species of fishes, amphibians, reptiles and mammals."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s32", "tokens": [{"t": "text", "v": "In Figure 15.1, biodiversity is depicted showing species number of major taxa."}], "blanks": [], "text": "In Figure 15.1, biodiversity is depicted showing species number of major taxa."}, {"type": "caption", "content": "Figure 15.1 Representing global biodiversity: proportionate number of species of major taxa of plants, invertebrates and vertebrates"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s33", "tokens": [{"t": "text", "v": "It should be noted that these estimates do not give any figures for "}, {"t": "cloze", "v": "prokaryotes"}, {"t": "text", "v": "."}], "blanks": ["prokaryotes"], "text": "It should be noted that these estimates do not give any figures for prokaryotes."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s34", "tokens": [{"t": "text", "v": "Biologists are not sure about how many prokaryotic species there might be."}], "blanks": [], "text": "Biologists are not sure about how many prokaryotic species there might be."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s35", "tokens": [{"t": "text", "v": "The problem is that conventional taxonomic methods are not suitable for identifying microbial species and many species are simply not culturable under laboratory conditions."}], "blanks": [], "text": "The problem is that conventional taxonomic methods are not suitable for identifying microbial species and many species are simply not culturable under laboratory conditions."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s36", "tokens": [{"t": "text", "v": "If we accept biochemical or molecular criteria for delineating species for this group, then their diversity alone might run into millions."}], "blanks": [], "text": "If we accept biochemical or molecular criteria for delineating species for this group, then their diversity alone might run into millions."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s37", "tokens": [{"t": "text", "v": "Although India h as only "}, {"t": "cloze", "v": "2.4 per cent"}, {"t": "text", "v": " of the world’s land area, its share of the global species diversity is an impressive "}, {"t": "cloze", "v": "8.1 per cent"}, {"t": "text", "v": "."}], "blanks": ["2.4 per cent", "8.1 per cent"], "text": "Although India h as only 2.4 per cent of the world’s land area, its share of the global species diversity is an impressive 8.1 per cent."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s38", "tokens": [{"t": "text", "v": "That is what makes our country one of the "}, {"t": "cloze", "v": "12 mega diversity countries"}, {"t": "text", "v": " of the world."}], "blanks": ["12 mega diversity countries"], "text": "That is what makes our country one of the 12 mega diversity countries of the world."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s39", "tokens": [{"t": "text", "v": "Nearly "}, {"t": "cloze", "v": "45,000 species of plants"}, {"t": "text", "v": " and twice as many of animals have been recorded from India."}], "blanks": ["45,000 species of plants"], "text": "Nearly 45,000 species of plants and twice as many of animals have been recorded from India."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s40", "tokens": [{"t": "text", "v": "How many living species are actually there waiting to be discovered and named?"}], "blanks": [], "text": "How many living species are actually there waiting to be discovered and named?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s41", "tokens": [{"t": "text", "v": "If we accept "}, {"t": "cloze", "v": "May’s"}, {"t": "text", "v": " global estimates, only "}, {"t": "cloze", "v": "22 per cent"}, {"t": "text", "v": " of the total species have been recorded so far."}], "blanks": ["May’s", "22 per cent"], "text": "If we accept May’s global estimates, only 22 per cent of the total species have been recorded so far."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s42", "tokens": [{"t": "text", "v": "Applying this proportion to India’s diversity figures, we estimate that there are probably more than 1,00,000 plant species and more than 3,00 , 000 animal species yet to be discovered and described."}], "blanks": [], "text": "Applying this proportion to India’s diversity figures, we estimate that there are probably more than 1,00,000 plant species and more than 3,00 , 000 animal species yet to be discovered and described."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s43", "tokens": [{"t": "text", "v": "Would we ever be able to complete the inventory of the biological wealth of our country?"}], "blanks": [], "text": "Would we ever be able to complete the inventory of the biological wealth of our country?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s44", "tokens": [{"t": "text", "v": "Consider the immense trained manpower (taxonomists) and the time required to complete the job."}], "blanks": [], "text": "Consider the immense trained manpower (taxonomists) and the time required to complete the job."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s45", "tokens": [{"t": "text", "v": "The situation appears more hopeless when we realise that a large fraction of these species faces the threat of becoming extinct even before we discover them."}], "blanks": [], "text": "The situation appears more hopeless when we realise that a large fraction of these species faces the threat of becoming extinct even before we discover them."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s46", "tokens": [{"t": "text", "v": "Nature’s biological library is burning even before we catalogued the titles of all the books stocked there."}], "blanks": [], "text": "Nature’s biological library is burning even before we catalogued the titles of all the books stocked there."}, {"type": "h3", "content": "15.1.2 Patterns of Biodiversity"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s47", "tokens": [{"t": "text", "v": "(i) Latitudinal gradient s : The diversity of plants and animals is not uniform throughout the world but shows a rather uneven distribution."}], "blanks": [], "text": "(i) Latitudinal gradient s : The diversity of plants and animals is not uniform throughout the world but shows a rather uneven distribution."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s48", "tokens": [{"t": "text", "v": "For many group of animals or plants, there are interesting patterns in diversity, the most well- known being the latitudinal gradient in diversity."}], "blanks": [], "text": "For many group of animals or plants, there are interesting patterns in diversity, the most well- known being the latitudinal gradient in diversity."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s49", "tokens": [{"t": "text", "v": "In general, species diversity decreases as we move away from the "}, {"t": "cloze", "v": "equator towards the poles"}, {"t": "text", "v": "."}], "blanks": ["equator towards the poles"], "text": "In general, species diversity decreases as we move away from the equator towards the poles."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s50", "tokens": [{"t": "text", "v": "With very few exceptions, "}, {"t": "cloze", "v": "tropics"}, {"t": "text", "v": " (latitudinal range of "}, {"t": "cloze", "v": "23.5° N to 23.5° S"}, {"t": "text", "v": ") harbour more species than temperate or polar areas."}], "blanks": ["tropics", "23.5° N to 23.5° S"], "text": "With very few exceptions, tropics (latitudinal range of 23.5° N to 23.5° S) harbour more species than temperate or polar areas."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s51", "tokens": [{"t": "text", "v": "Colombia located near the equator has nearly "}, {"t": "cloze", "v": "1,400 species of birds"}, {"t": "text", "v": " while New York at 41° N has "}, {"t": "cloze", "v": "105 species"}, {"t": "text", "v": " and Greenland at 71° N only "}, {"t": "cloze", "v": "56 species"}, {"t": "text", "v": "."}], "blanks": ["1,400 species of birds", "105 species", "56 species"], "text": "Colombia located near the equator has nearly 1,400 species of birds while New York at 41° N has 105 species and Greenland at 71° N only 56 species."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s52", "tokens": [{"t": "text", "v": "India, with much of its land area in the tropical latitudes, has more than "}, {"t": "cloze", "v": "1,200 species of birds"}, {"t": "text", "v": "."}], "blanks": ["1,200 species of birds"], "text": "India, with much of its land area in the tropical latitudes, has more than 1,200 species of birds."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s53", "tokens": [{"t": "text", "v": "A forest in a tropical region like Equador has up to "}, {"t": "cloze", "v": "10 times"}, {"t": "text", "v": " as many species of vascular plants as a forest of equal area in a temperate region like the Midwest of the USA."}], "blanks": ["10 times"], "text": "A forest in a tropical region like Equador has up to 10 times as many species of vascular plants as a forest of equal area in a temperate region like the Midwest of the USA."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s54", "tokens": [{"t": "text", "v": "The largely tropical Amazonian rain forest in South America has the greatest biodiversity on earth- it is home to more than "}, {"t": "cloze", "v": "40,000 species of plants"}, {"t": "text", "v": ", 3,000 of fishes, 1,300 of birds, 427 of mammals, 427 of amphibians, 378 of reptiles and of more than "}, {"t": "cloze", "v": "1,25,000 invertebrates"}, {"t": "text", "v": "."}], "blanks": ["40,000 species of plants", "1,25,000 invertebrates"], "text": "The largely tropical Amazonian rain forest in South America has the greatest biodiversity on earth- it is home to more than 40,000 species of plants, 3,000 of fishes, 1,300 of birds, 427 of mammals, 427 of amphibians, 378 of reptiles and of more than 1,25,000 invertebrates."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s55", "tokens": [{"t": "text", "v": "Scientists estimate that in these rain forests there might be at least "}, {"t": "cloze", "v": "two million"}, {"t": "text", "v": " insect species waiting to be discovered and named."}], "blanks": ["two million"], "text": "Scientists estimate that in these rain forests there might be at least two million insect species waiting to be discovered and named."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s56", "tokens": [{"t": "text", "v": "What is so special about tropics that might account for their greater biological diversity?"}], "blanks": [], "text": "What is so special about tropics that might account for their greater biological diversity?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s57", "tokens": [{"t": "text", "v": "Ecologists and evolutionary biologists have proposed various hypotheses; some important ones are (a) Speciation is generally a function of time, unlike temperate regions subjected to frequent glaciations in the past, tropical latitudes have remained relatively undisturbed for millions of ye ars and thus, had a long evolutionary time for species diversification , (b) Tropical environments, unlike temperate ones, are less seasonal, relatively more constant and predictable."}], "blanks": [], "text": "Ecologists and evolutionary biologists have proposed various hypotheses; some important ones are (a) Speciation is generally a function of time, unlike temperate regions subjected to frequent glaciations in the past, tropical latitudes have remained relatively undisturbed for millions of ye ars and thus, had a long evolutionary time for species diversification , (b) Tropical environments, unlike temperate ones, are less seasonal, relatively more constant and predictable."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s58", "tokens": [{"t": "text", "v": "Such constant environments promote niche specialisation and lead to a greater species diversity and (c) There is more solar energy available in the tropics, which contributes to higher productivity; this in turn might contribute indirectly to greater diversity."}], "blanks": [], "text": "Such constant environments promote niche specialisation and lead to a greater species diversity and (c) There is more solar energy available in the tropics, which contributes to higher productivity; this in turn might contribute indirectly to greater diversity."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s59", "tokens": [{"t": "text", "v": "(ii) Species-Area relationship s : During his pioneering and extensive explorations in the wilderness of South American jungles, the great German naturalist and geographer "}, {"t": "cloze", "v": "Alexander von Humboldt"}, {"t": "text", "v": " observed that within a region species richness increased with increasing explored area, but only up to a limit."}], "blanks": ["Alexander von Humboldt"], "text": "(ii) Species-Area relationship s : During his pioneering and extensive explorations in the wilderness of South American jungles, the great German naturalist and geographer Alexander von Humboldt observed that within a region species richness increased with increasing explored area, but only up to a limit."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s60", "tokens": [{"t": "text", "v": "In fact, the relation between species richness and area for a wide variety of taxa (angiosperm plants, birds, bats, freshwater fishes) turns out to be a "}, {"t": "cloze", "v": "rectangular hyperbola"}, {"t": "text", "v": " (Figure15.2)."}], "blanks": ["rectangular hyperbola"], "text": "In fact, the relation between species richness and area for a wide variety of taxa (angiosperm plants, birds, bats, freshwater fishes) turns out to be a rectangular hyperbola (Figure15.2)."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s61", "tokens": [{"t": "text", "v": "On a logarithmic scale, the relationship is a "}, {"t": "cloze", "v": "straight line"}, {"t": "text", "v": " described by the equation"}], "blanks": ["straight line"], "text": "On a logarithmic scale, the relationship is a straight line described by the equation"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s62", "tokens": [{"t": "cloze", "v": "log S = log c + z log A"}], "blanks": ["log S = log c + z log A"], "text": "log S = log c + z log A"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s63", "tokens": [{"t": "text", "v": "where"}], "blanks": [], "text": "where"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s64", "tokens": [{"t": "text", "v": "S= "}, {"t": "cloze", "v": "Species richness"}, {"t": "text", "v": " A= Area"}], "blanks": ["Species richness"], "text": "S= Species richness A= Area"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s65", "tokens": [{"t": "text", "v": "z = slope of the line ("}, {"t": "cloze", "v": "regression coefficient"}, {"t": "text", "v": ")"}], "blanks": ["regression coefficient"], "text": "z = slope of the line (regression coefficient)"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s66", "tokens": [{"t": "text", "v": "c = "}, {"t": "cloze", "v": "Y-intercept"}], "blanks": ["Y-intercept"], "text": "c = Y-intercept"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s67", "tokens": [{"t": "text", "v": "Ecologists have discovered that the value of z lies in the range of "}, {"t": "cloze", "v": "0.1 to 0.2"}, {"t": "text", "v": ", regardless of the taxonomic group or the region (whether it is the plants in Britain, birds in California or molluscs in New York state, the slopes of the regression line are amazingly similar)."}], "blanks": ["0.1 to 0.2"], "text": "Ecologists have discovered that the value of z lies in the range of 0.1 to 0.2, regardless of the taxonomic group or the region (whether it is the plants in Britain, birds in California or molluscs in New York state, the slopes of the regression line are amazingly similar)."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s68", "tokens": [{"t": "text", "v": "But, if you analyse the species-area relationships among very large areas like the entire continents, you will find that the slope of the line to be much steeper ( z values in the range of "}, {"t": "cloze", "v": "0.6 to 1.2"}, {"t": "text", "v": ")."}], "blanks": ["0.6 to 1.2"], "text": "But, if you analyse the species-area relationships among very large areas like the entire continents, you will find that the slope of the line to be much steeper ( z values in the range of 0.6 to 1.2)."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s69", "tokens": [{"t": "text", "v": "For example, for frugivorous (fruit-eating) birds and mammals in the tropical forests of different continents, the slope is found to be "}, {"t": "cloze", "v": "1.15"}, {"t": "text", "v": "."}], "blanks": ["1.15"], "text": "For example, for frugivorous (fruit-eating) birds and mammals in the tropical forests of different continents, the slope is found to be 1.15."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s70", "tokens": [{"t": "text", "v": "What do steeper slopes mean in this context?"}], "blanks": [], "text": "What do steeper slopes mean in this context?"}, {"type": "h3", "content": "15.1.3 The importance of Species Diversity to the Ecosystem"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s71", "tokens": [{"t": "text", "v": "Does the number of species in a community really matter to the functioning of the ecosystem?This is a question for which ecologists have not been able to give a definitive answer."}], "blanks": [], "text": "Does the number of species in a community really matter to the functioning of the ecosystem?This is a question for which ecologists have not been able to give a definitive answer."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s72", "tokens": [{"t": "text", "v": "For many decades, ecologists believed that communities with more species, generally, tend to be more stable than those with less species."}], "blanks": [], "text": "For many decades, ecologists believed that communities with more species, generally, tend to be more stable than those with less species."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s73", "tokens": [{"t": "text", "v": "What exactly is stability for a biological community?"}], "blanks": [], "text": "What exactly is stability for a biological community?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s74", "tokens": [{"t": "text", "v": "A stable community should not show too much variation in productivity from year to year; it must be either resistant or resilient to occasional disturbances (natural or man-made), and it must also be resistant to invasions by alien species."}], "blanks": [], "text": "A stable community should not show too much variation in productivity from year to year; it must be either resistant or resilient to occasional disturbances (natural or man-made), and it must also be resistant to invasions by alien species."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s75", "tokens": [{"t": "text", "v": "We don’t know how these attributes are linked to species richness in a community, but "}, {"t": "cloze", "v": "David Tilman"}, {"t": "text", "v": "’s long- term ecosystem experiments using outdoor plots provide some tentative answers."}], "blanks": ["David Tilman"], "text": "We don’t know how these attributes are linked to species richness in a community, but David Tilman’s long- term ecosystem experiments using outdoor plots provide some tentative answers."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s76", "tokens": [{"t": "cloze", "v": "Tilman"}, {"t": "text", "v": " found that plots with more species showed less year-to-year variation in total biomass."}], "blanks": ["Tilman"], "text": "Tilman found that plots with more species showed less year-to-year variation in total biomass."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s77", "tokens": [{"t": "text", "v": "He also showed that in his experiments, increased diversity contributed to higher productivity."}], "blanks": [], "text": "He also showed that in his experiments, increased diversity contributed to higher productivity."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s78", "tokens": [{"t": "text", "v": "Although, we may not understand completely how species richness contributes to the well-being of an ecosystem, we know enough to realise that rich biodiversity is not only essential for ecosystem health but imperative for the very survival of the human race on this planet."}], "blanks": [], "text": "Although, we may not understand completely how species richness contributes to the well-being of an ecosystem, we know enough to realise that rich biodiversity is not only essential for ecosystem health but imperative for the very survival of the human race on this planet."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s79", "tokens": [{"t": "text", "v": "At a time when we are losing species at an alarming pace, one might ask– Does it really matter to us if a few species become extinct?"}], "blanks": [], "text": "At a time when we are losing species at an alarming pace, one might ask– Does it really matter to us if a few species become extinct?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s80", "tokens": [{"t": "text", "v": "Would "}, {"t": "cloze", "v": "Western Ghats"}, {"t": "text", "v": " ecosystems be less functional if one of its tree frog species is lost forever?"}], "blanks": ["Western Ghats"], "text": "Would Western Ghats ecosystems be less functional if one of its tree frog species is lost forever?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s81", "tokens": [{"t": "text", "v": "How is our quality of life affected if, say, instead of 20,000 we have only 15,000 species of ants on earth?"}], "blanks": [], "text": "How is our quality of life affected if, say, instead of 20,000 we have only 15,000 species of ants on earth?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s82", "tokens": [{"t": "text", "v": "There are no direct answers to such näive questions but we can develop a proper perspective through an analogy (the ‘"}, {"t": "cloze", "v": "rivet popper hypothesis"}, {"t": "text", "v": "’) used by Stanford ecologist "}, {"t": "cloze", "v": "Paul Ehrlich"}, {"t": "text", "v": "."}], "blanks": ["rivet popper hypothesis", "Paul Ehrlich"], "text": "There are no direct answers to such näive questions but we can develop a proper perspective through an analogy (the ‘rivet popper hypothesis’) used by Stanford ecologist Paul Ehrlich."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s83", "tokens": [{"t": "text", "v": "In an airplane (ecosystem) all parts are joined toge ther using thousands of rivets (species)."}], "blanks": [], "text": "In an airplane (ecosystem) all parts are joined toge ther using thousands of rivets (species)."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s84", "tokens": [{"t": "text", "v": "If every passenger travelling in it starts popping a rivet to take home (causing a species to become extinct), it may not affect flight safety (proper functioning of the ecosystem) initially, but as more and more rivets are removed, the plane becomes dangerously weak over a period of time."}], "blanks": [], "text": "If every passenger travelling in it starts popping a rivet to take home (causing a species to become extinct), it may not affect flight safety (proper functioning of the ecosystem) initially, but as more and more rivets are removed, the plane becomes dangerously weak over a period of time."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s85", "tokens": [{"t": "text", "v": "Furthermore, which rivet is removed may also be critical. Loss of rivets on the wings (key species that drive major ecosystem functions) is obviously a more serious threat to flight safety than loss of a few rivets on the seats or windows inside the plane."}], "blanks": [], "text": "Furthermore, which rivet is removed may also be critical. Loss of rivets on the wings (key species that drive major ecosystem functions) is obviously a more serious threat to flight safety than loss of a few rivets on the seats or windows inside the plane."}, {"type": "h3", "content": "15.1.4 Loss of Biodiversity"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s86", "tokens": [{"t": "text", "v": "While it is doubtful if any new species are being added (through speciation) into the earth’s treasury of species, there is no doubt about their continuing losses."}], "blanks": [], "text": "While it is doubtful if any new species are being added (through speciation) into the earth’s treasury of species, there is no doubt about their continuing losses."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s87", "tokens": [{"t": "text", "v": "The biological wealth of our planet has been declining rapidly and the accusing finger is clearly pointing to human activities."}], "blanks": [], "text": "The biological wealth of our planet has been declining rapidly and the accusing finger is clearly pointing to human activities."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s88", "tokens": [{"t": "text", "v": "The colonisation of tropical Pacific Islands by humans is said to have led to the extinction of more than "}, {"t": "cloze", "v": "2,000 species"}, {"t": "text", "v": " of native birds."}], "blanks": ["2,000 species"], "text": "The colonisation of tropical Pacific Islands by humans is said to have led to the extinction of more than 2,000 species of native birds."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s89", "tokens": [{"t": "text", "v": "The "}, {"t": "cloze", "v": "IUCN Red List (2004)"}, {"t": "text", "v": " documents the extinction of "}, {"t": "cloze", "v": "784 species"}, {"t": "text", "v": " (including 338 vertebrates, 359 invertebrates and 87 plants) in the last 500 years."}], "blanks": ["IUCN Red List (2004)", "784 species"], "text": "The IUCN Red List (2004) documents the extinction of 784 species (including 338 vertebrates, 359 invertebrates and 87 plants) in the last 500 years."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s90", "tokens": [{"t": "text", "v": "Some examples of recent extinctions include the "}, {"t": "cloze", "v": "dodo"}, {"t": "text", "v": " (Mauritius), "}, {"t": "cloze", "v": "quagga"}, {"t": "text", "v": " (Africa), "}, {"t": "cloze", "v": "thylacine"}, {"t": "text", "v": " (Australia), "}, {"t": "cloze", "v": "Steller’s Sea Cow"}, {"t": "text", "v": " (Russia) and three subspecies (Bali, Javan, Caspian) of tiger."}], "blanks": ["dodo", "quagga", "thylacine", "Steller’s Sea Cow"], "text": "Some examples of recent extinctions include the dodo (Mauritius), quagga (Africa), thylacine (Australia), Steller’s Sea Cow (Russia) and three subspecies (Bali, Javan, Caspian) of tiger."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s91", "tokens": [{"t": "text", "v": "The last twenty years alone have witnessed the disappearance of 27 species."}], "blanks": [], "text": "The last twenty years alone have witnessed the disappearance of 27 species."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s92", "tokens": [{"t": "text", "v": "Careful analysis of records shows that extinctions across taxa are not rando m; some groups like "}, {"t": "cloze", "v": "amphibians"}, {"t": "text", "v": " appear to be more vulnerable to extinction."}], "blanks": ["amphibians"], "text": "Careful analysis of records shows that extinctions across taxa are not rando m; some groups like amphibians appear to be more vulnerable to extinction."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s93", "tokens": [{"t": "text", "v": "Adding to the grim scenario of extinctions is the fact that more than "}, {"t": "cloze", "v": "15,500 species"}, {"t": "text", "v": " world-wide are facing the threat of extinction."}], "blanks": ["15,500 species"], "text": "Adding to the grim scenario of extinctions is the fact that more than 15,500 species world-wide are facing the threat of extinction."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s94", "tokens": [{"t": "text", "v": "Presently, "}, {"t": "cloze", "v": "12 per cent"}, {"t": "text", "v": " of all bird species, "}, {"t": "cloze", "v": "23 per cent"}, {"t": "text", "v": " of all mammal species, "}, {"t": "cloze", "v": "32 per cent"}, {"t": "text", "v": " of all amphibian species and "}, {"t": "cloze", "v": "31per cent"}, {"t": "text", "v": " of all gymnosperm species in the world face the threat of extinction."}], "blanks": ["12 per cent", "23 per cent", "32 per cent", "31per cent"], "text": "Presently, 12 per cent of all bird species, 23 per cent of all mammal species, 32 per cent of all amphibian species and 31per cent of all gymnosperm species in the world face the threat of extinction."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s95", "tokens": [{"t": "text", "v": "From a study of the history of life on earth through fossil records, we learn that large-scale loss of species like the one we are currently witnessing have also happened earlier, even before humans appeared on the scene."}], "blanks": [], "text": "From a study of the history of life on earth through fossil records, we learn that large-scale loss of species like the one we are currently witnessing have also happened earlier, even before humans appeared on the scene."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s96", "tokens": [{"t": "text", "v": "During the long period (> 3 billion years) since the origin and diversification of life on earth there were "}, {"t": "cloze", "v": "five episodes of mass extinction"}, {"t": "text", "v": " of species."}], "blanks": ["five episodes of mass extinction"], "text": "During the long period (> 3 billion years) since the origin and diversification of life on earth there were five episodes of mass extinction of species."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s97", "tokens": [{"t": "text", "v": "How is the "}, {"t": "cloze", "v": "‘Sixth Extinction’"}, {"t": "text", "v": " presently in progress different from the previous episodes?"}], "blanks": ["‘Sixth Extinction’"], "text": "How is the ‘Sixth Extinction’ presently in progress different from the previous episodes?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s98", "tokens": [{"t": "text", "v": "The difference is in the rates; the current species extinction rates are estimated to be "}, {"t": "cloze", "v": "100 to 1,000 times faster"}, {"t": "text", "v": " than in the pre-human times and our activities are responsible for the faster rates."}], "blanks": ["100 to 1,000 times faster"], "text": "The difference is in the rates; the current species extinction rates are estimated to be 100 to 1,000 times faster than in the pre-human times and our activities are responsible for the faster rates."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s99", "tokens": [{"t": "text", "v": "Ecologists warn that if the present trends continue, nearly half of all the species on earth might be wiped out within the next 100 years."}], "blanks": [], "text": "Ecologists warn that if the present trends continue, nearly half of all the species on earth might be wiped out within the next 100 years."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s100", "tokens": [{"t": "text", "v": "In general, loss of biodiversity in a region may lead to (a) decline in plant production, (b) lowered resistance to environmental perturbations such as drought and ( c) increased variability in certain ecosystem processes such as plant productivity, water use, and pest and disease cycles."}], "blanks": [], "text": "In general, loss of biodiversity in a region may lead to (a) decline in plant production, (b) lowered resistance to environmental perturbations such as drought and ( c) increased variability in certain ecosystem processes such as plant productivity, water use, and pest and disease cycles."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s101", "tokens": [{"t": "text", "v": "Causes of biodiversity losses : The accelerated rates of species extinctions that the world is facing now are largely due to human activities."}], "blanks": [], "text": "Causes of biodiversity losses : The accelerated rates of species extinctions that the world is facing now are largely due to human activities."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s102", "tokens": [{"t": "text", "v": "There are four major causes (‘ "}, {"t": "cloze", "v": "The Evil Quartet"}, {"t": "text", "v": " ’ is the sobriquet used to describe them)."}], "blanks": ["The Evil Quartet"], "text": "There are four major causes (‘ The Evil Quartet ’ is the sobriquet used to describe them)."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s103", "tokens": [{"t": "text", "v": "(i) "}, {"t": "cloze", "v": "Habitat loss and fragmentation"}, {"t": "text", "v": " : This is the most important cause driving animals and plants to extinction."}], "blanks": ["Habitat loss and fragmentation"], "text": "(i) Habitat loss and fragmentation : This is the most important cause driving animals and plants to extinction."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s104", "tokens": [{"t": "text", "v": "The most dramatic examples of habitat loss come from "}, {"t": "cloze", "v": "tropical rain forests"}, {"t": "text", "v": "."}], "blanks": ["tropical rain forests"], "text": "The most dramatic examples of habitat loss come from tropical rain forests."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s105", "tokens": [{"t": "text", "v": "Once covering more than "}, {"t": "cloze", "v": "14 per cent"}, {"t": "text", "v": " of the earth’s land surface, these rain forests now cover no more than "}, {"t": "cloze", "v": "6 per cent"}, {"t": "text", "v": "."}], "blanks": ["14 per cent", "6 per cent"], "text": "Once covering more than 14 per cent of the earth’s land surface, these rain forests now cover no more than 6 per cent."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s106", "tokens": [{"t": "text", "v": "They are being destroyed fast."}], "blanks": [], "text": "They are being destroyed fast."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s107", "tokens": [{"t": "text", "v": "By the time you finish reading this chapter, 1000 more hectares of rain forest would have been lost."}], "blanks": [], "text": "By the time you finish reading this chapter, 1000 more hectares of rain forest would have been lost."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s108", "tokens": [{"t": "text", "v": "The "}, {"t": "cloze", "v": "Amazon rain forest"}, {"t": "text", "v": " (it is so huge that it is called the ‘"}, {"t": "cloze", "v": "lungs of the planet"}, {"t": "text", "v": "’) harbouring probably millions of species is being cut and cleared for cultivating soya beans or for conversion to grasslands for raising beef cattle."}], "blanks": ["Amazon rain forest", "lungs of the planet"], "text": "The Amazon rain forest (it is so huge that it is called the ‘lungs of the planet’) harbouring probably millions of species is being cut and cleared for cultivating soya beans or for conversion to grasslands for raising beef cattle."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s109", "tokens": [{"t": "text", "v": "Besides total loss, the degradation of many habitats by pollution also threatens the survival of many species."}], "blanks": [], "text": "Besides total loss, the degradation of many habitats by pollution also threatens the survival of many species."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s110", "tokens": [{"t": "text", "v": "When large habitats are broken up into small fragments due to various human activities, mammals and birds requiring large territories and certain animals with migratory habits are badly affected, leading to population declines."}], "blanks": [], "text": "When large habitats are broken up into small fragments due to various human activities, mammals and birds requiring large territories and certain animals with migratory habits are badly affected, leading to population declines."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s111", "tokens": [{"t": "text", "v": "(ii) "}, {"t": "cloze", "v": "Over-exploitation"}, {"t": "text", "v": " : Humans have always depended on nature for food and shelter, but when ‘need’ turns to ‘greed’, it leads to over- exploitation of natural resources."}], "blanks": ["Over-exploitation"], "text": "(ii) Over-exploitation : Humans have always depended on nature for food and shelter, but when ‘need’ turns to ‘greed’, it leads to over- exploitation of natural resources."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s112", "tokens": [{"t": "text", "v": "Many species extinctions in the last "}, {"t": "cloze", "v": "500 years"}, {"t": "text", "v": " ("}, {"t": "cloze", "v": "Steller’s sea cow"}, {"t": "text", "v": ", passenger pigeon) were due to overexploitation by humans."}], "blanks": ["500 years", "Steller’s sea cow"], "text": "Many species extinctions in the last 500 years (Steller’s sea cow, passenger pigeon) were due to overexploitation by humans."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s113", "tokens": [{"t": "text", "v": "Presently many marine fish populations around the world are over harvested, endangering the continued existence of some commercially important species."}], "blanks": [], "text": "Presently many marine fish populations around the world are over harvested, endangering the continued existence of some commercially important species."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s114", "tokens": [{"t": "text", "v": "(iii) "}, {"t": "cloze", "v": "Alien species invasions"}, {"t": "text", "v": " : When alien species are introduced unintentionally or deliberately for whatever purpose, some of them turn invasive, and cause decline or extinction of indigenous species."}], "blanks": ["Alien species invasions"], "text": "(iii) Alien species invasions : When alien species are introduced unintentionally or deliberately for whatever purpose, some of them turn invasive, and cause decline or extinction of indigenous species."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s115", "tokens": [{"t": "text", "v": "The "}, {"t": "cloze", "v": "Nile perch"}, {"t": "text", "v": " introduced into "}, {"t": "cloze", "v": "Lake Victoria"}, {"t": "text", "v": " in east Africa led eventually to the extinction of an ecologically unique assemblage of more than 200 species of cichlid fish in the lake."}], "blanks": ["Nile perch", "Lake Victoria"], "text": "The Nile perch introduced into Lake Victoria in east Africa led eventually to the extinction of an ecologically unique assemblage of more than 200 species of cichlid fish in the lake."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s116", "tokens": [{"t": "text", "v": "You must be familiar with the environmental damage caused and threat posed to our native species by invasive weed species like carrot grass ( "}, {"t": "cloze", "v": "Parthenium"}, {"t": "text", "v": " ) , Lantana and water hyacinth ( "}, {"t": "cloze", "v": "Eicchornia"}, {"t": "text", "v": " ) ."}], "blanks": ["Parthenium", "Eicchornia"], "text": "You must be familiar with the environmental damage caused and threat posed to our native species by invasive weed species like carrot grass ( Parthenium ) , Lantana and water hyacinth ( Eicchornia ) ."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s117", "tokens": [{"t": "text", "v": "The recent illegal introduction of the African catfish "}, {"t": "cloze", "v": "Clarias gariepinus"}, {"t": "text", "v": " for aquaculture purposes is posing a threat to the indigenous catfishes in our rivers."}], "blanks": ["Clarias gariepinus"], "text": "The recent illegal introduction of the African catfish Clarias gariepinus for aquaculture purposes is posing a threat to the indigenous catfishes in our rivers."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s118", "tokens": [{"t": "text", "v": "(iv) "}, {"t": "cloze", "v": "Co-extinctions"}, {"t": "text", "v": " : When a species becomes extinct, the plant and animal species associated with it in an obligatory way also become extinct."}], "blanks": ["Co-extinctions"], "text": "(iv) Co-extinctions : When a species becomes extinct, the plant and animal species associated with it in an obligatory way also become extinct."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s119", "tokens": [{"t": "text", "v": "When a host fish species becomes extinct, its unique assemblage of parasites also meets the same fate."}], "blanks": [], "text": "When a host fish species becomes extinct, its unique assemblage of parasites also meets the same fate."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s120", "tokens": [{"t": "text", "v": "Another example is the case of a coevolved plant-pollinator mutualism where extinction of one invariably leads to the extinction of the other."}], "blanks": [], "text": "Another example is the case of a coevolved plant-pollinator mutualism where extinction of one invariably leads to the extinction of the other."}, {"type": "h2", "content": "15.2 Biodiversity Conservation"}, {"type": "h3", "content": "15.2.1 Why Should We Conserve Biodiversity?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s121", "tokens": [{"t": "text", "v": "There are many reasons, some obvious and others not so obvious, but all equally important."}], "blanks": [], "text": "There are many reasons, some obvious and others not so obvious, but all equally important."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s122", "tokens": [{"t": "text", "v": "They can be grouped into three categories: "}, {"t": "cloze", "v": "narrowly utilitarian, broadly utilitarian, and ethical"}, {"t": "text", "v": "."}], "blanks": ["narrowly utilitarian, broadly utilitarian, and ethical"], "text": "They can be grouped into three categories: narrowly utilitarian, broadly utilitarian, and ethical."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s123", "tokens": [{"t": "text", "v": "The narrowly utilitarian arguments for conserving biodiversity are obvious; humans derive countless direct economic benefits from nature- food (cereals, pulses, fruits), firewood, fibre, construction material, industrial products (tannins, lubricants, dyes, resins, perfumes ) and products of medicinal importance."}], "blanks": [], "text": "The narrowly utilitarian arguments for conserving biodiversity are obvious; humans derive countless direct economic benefits from nature- food (cereals, pulses, fruits), firewood, fibre, construction material, industrial products (tannins, lubricants, dyes, resins, perfumes ) and products of medicinal importance."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s124", "tokens": [{"t": "text", "v": "More than "}, {"t": "cloze", "v": "25 per cent"}, {"t": "text", "v": " of the drugs currently sold in the market worldwide are derived from plants and "}, {"t": "cloze", "v": "25,000"}, {"t": "text", "v": " species of plants contribute to the traditional medicines used by native peoples around the world."}], "blanks": ["25 per cent", "25,000"], "text": "More than 25 per cent of the drugs currently sold in the market worldwide are derived from plants and 25,000 species of plants contribute to the traditional medicines used by native peoples around the world."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s125", "tokens": [{"t": "text", "v": "Nobody knows how many more medicinally useful plants there are in tropical rain forests waiting to be explored."}], "blanks": [], "text": "Nobody knows how many more medicinally useful plants there are in tropical rain forests waiting to be explored."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s126", "tokens": [{"t": "text", "v": "With increasing resources put into ‘"}, {"t": "cloze", "v": "bioprospecting"}, {"t": "text", "v": "’ (exploring molecular, genetic and species-level diversity for products of economic importance), nations endowed with rich biodiversity can expect to reap enormous benefits."}], "blanks": ["bioprospecting"], "text": "With increasing resources put into ‘bioprospecting’ (exploring molecular, genetic and species-level diversity for products of economic importance), nations endowed with rich biodiversity can expect to reap enormous benefits."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s127", "tokens": [{"t": "text", "v": "The broadly utilitarian argument says that biodiversity plays a major role in many ecosystem services that nature provides."}], "blanks": [], "text": "The broadly utilitarian argument says that biodiversity plays a major role in many ecosystem services that nature provides."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s128", "tokens": [{"t": "text", "v": "The fast- dwindling Amazon forest is estimated to produce, through photosynthesis, "}, {"t": "cloze", "v": "20 per cent"}, {"t": "text", "v": " of the total oxygen in the earth’s atmosphere."}], "blanks": ["20 per cent"], "text": "The fast- dwindling Amazon forest is estimated to produce, through photosynthesis, 20 per cent of the total oxygen in the earth’s atmosphere."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s129", "tokens": [{"t": "text", "v": "Can we put an economic value on this service by nature?"}], "blanks": [], "text": "Can we put an economic value on this service by nature?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s130", "tokens": [{"t": "text", "v": "You can get some idea by finding out how much your neighborhood hospital spends on a cylinder of oxygen."}], "blanks": [], "text": "You can get some idea by finding out how much your neighborhood hospital spends on a cylinder of oxygen."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s131", "tokens": [{"t": "text", "v": "Pollination (without which plants cannot give us fruits or seeds) is another service, ecosystems provide through pollinators layer – bees, bumblebees, birds and bats."}], "blanks": [], "text": "Pollination (without which plants cannot give us fruits or seeds) is another service, ecosystems provide through pollinators layer – bees, bumblebees, birds and bats."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s132", "tokens": [{"t": "text", "v": "What will be the costs of accomplishing pollination without help from natural pollinators?"}], "blanks": [], "text": "What will be the costs of accomplishing pollination without help from natural pollinators?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s133", "tokens": [{"t": "text", "v": "There are other intangible benefits – that we derive from natur e– the aesthetic pleasures of walking through thick woods, watching spring flowers in full bloom or waking up to a bulbul’s song in the morning."}], "blanks": [], "text": "There are other intangible benefits – that we derive from natur e– the aesthetic pleasures of walking through thick woods, watching spring flowers in full bloom or waking up to a bulbul’s song in the morning."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s134", "tokens": [{"t": "text", "v": "Can we put a price tag on such things?"}], "blanks": [], "text": "Can we put a price tag on such things?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s135", "tokens": [{"t": "text", "v": "The ethical argument for conserving biodiversity relates to what we owe to millions of plant, animal and microbe species with whom we share this planet."}], "blanks": [], "text": "The ethical argument for conserving biodiversity relates to what we owe to millions of plant, animal and microbe species with whom we share this planet."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s136", "tokens": [{"t": "text", "v": "Philosophically or spiritually, we need to realise that every species has an intrinsic value, even if it may not be of current or any economic value to us."}], "blanks": [], "text": "Philosophically or spiritually, we need to realise that every species has an intrinsic value, even if it may not be of current or any economic value to us."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s137", "tokens": [{"t": "text", "v": "We have a moral duty to care for their well-being and pass on our biological legacy in good order to future generations."}], "blanks": [], "text": "We have a moral duty to care for their well-being and pass on our biological legacy in good order to future generations."}, {"type": "h3", "content": "15.2.2 How do we conserve Biodiversity?"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s138", "tokens": [{"t": "text", "v": "When we conserve and protect the whole ecosystem, its biodiversity at all levels is protected - we save the entire forest to save the tiger."}], "blanks": [], "text": "When we conserve and protect the whole ecosystem, its biodiversity at all levels is protected - we save the entire forest to save the tiger."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s139", "tokens": [{"t": "text", "v": "This approach is called "}, {"t": "cloze", "v": "in situ (on site)"}, {"t": "text", "v": " conservation."}], "blanks": ["in situ (on site)"], "text": "This approach is called in situ (on site) conservation."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s140", "tokens": [{"t": "text", "v": "However, when there are situations where an animal or plant is endangered or threatened (organisms facing a very high risk of extinction in the wild in the near future) and needs urgent measures to save it from extinction, "}, {"t": "cloze", "v": "ex situ (off site)"}, {"t": "text", "v": " conservation is the desirable approach."}], "blanks": ["ex situ (off site)"], "text": "However, when there are situations where an animal or plant is endangered or threatened (organisms facing a very high risk of extinction in the wild in the near future) and needs urgent measures to save it from extinction, ex situ (off site) conservation is the desirable approach."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s141", "tokens": [{"t": "text", "v": "In situ conservation– Faced with the conflict between development and conservation, many nations find it unrealistic and economically not feasible to conserve all their biological wealth."}], "blanks": [], "text": "In situ conservation– Faced with the conflict between development and conservation, many nations find it unrealistic and economically not feasible to conserve all their biological wealth."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s142", "tokens": [{"t": "text", "v": "Invariably, the number of species waiting to be saved from extinction far exceeds the conservation resources available."}], "blanks": [], "text": "Invariably, the number of species waiting to be saved from extinction far exceeds the conservation resources available."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s143", "tokens": [{"t": "text", "v": "On a global basis, this problem has been addressed by eminent conservationists."}], "blanks": [], "text": "On a global basis, this problem has been addressed by eminent conservationists."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s144", "tokens": [{"t": "text", "v": "They identified for maximum protection certain ‘biodiversity hotspots’ regions with very high levels of species richness and high degree of "}, {"t": "cloze", "v": "endemism"}, {"t": "text", "v": " (that is, species confined to that region and not found anywhere else)."}], "blanks": ["endemism"], "text": "They identified for maximum protection certain ‘biodiversity hotspots’ regions with very high levels of species richness and high degree of endemism (that is, species confined to that region and not found anywhere else)."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s145", "tokens": [{"t": "text", "v": "Initially 25 biodiversity hotspots were identified but subsequently nine more have been added to the list, bringing the total number of biodiversity hotspots in the world to 34."}], "blanks": [], "text": "Initially 25 biodiversity hotspots were identified but subsequently nine more have been added to the list, bringing the total number of biodiversity hotspots in the world to 34."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s146", "tokens": [{"t": "text", "v": "These hotspots are also regions of accelerated habitat loss."}], "blanks": [], "text": "These hotspots are also regions of accelerated habitat loss."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s147", "tokens": [{"t": "text", "v": "Three of these hotspots – "}, {"t": "cloze", "v": "Western Ghats and Sri Lanka"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "Indo-Burma and Himalaya"}, {"t": "text", "v": " – cover our country’s exceptionally high biodiversity regions."}], "blanks": ["Western Ghats and Sri Lanka", "Indo-Burma and Himalaya"], "text": "Three of these hotspots – Western Ghats and Sri Lanka, Indo-Burma and Himalaya – cover our country’s exceptionally high biodiversity regions."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s148", "tokens": [{"t": "text", "v": "Although all the biodiversity hotspots put together cover "}, {"t": "cloze", "v": "less than 2 per cent"}, {"t": "text", "v": " of the earth’s land area, the number of species they collectively harbour is extremely high and strict protection of these hotspots could reduce the ongoing mass extinctions by almost "}, {"t": "cloze", "v": "30 per cent"}, {"t": "text", "v": "."}], "blanks": ["less than 2 per cent", "30 per cent"], "text": "Although all the biodiversity hotspots put together cover less than 2 per cent of the earth’s land area, the number of species they collectively harbour is extremely high and strict protection of these hotspots could reduce the ongoing mass extinctions by almost 30 per cent."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s149", "tokens": [{"t": "text", "v": "In India, ecologically unique and biodiversity-rich regions are legally protected as biosphere reserves, national parks and sanctuaries."}], "blanks": [], "text": "In India, ecologically unique and biodiversity-rich regions are legally protected as biosphere reserves, national parks and sanctuaries."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s150", "tokens": [{"t": "text", "v": "India now has "}, {"t": "cloze", "v": "14 biosphere reserves"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "90 national parks"}, {"t": "text", "v": " and 448 wildlife sanctuaries."}], "blanks": ["14 biosphere reserves", "90 national parks"], "text": "India now has 14 biosphere reserves, 90 national parks and 448 wildlife sanctuaries."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s151", "tokens": [{"t": "text", "v": "India has also a history of religious and cultural traditions that emphasised protection of nature."}], "blanks": [], "text": "India has also a history of religious and cultural traditions that emphasised protection of nature."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s152", "tokens": [{"t": "text", "v": "In many cultures, tracts of forest were set aside, and all the trees and wildlife within were venerated and given total protection."}], "blanks": [], "text": "In many cultures, tracts of forest were set aside, and all the trees and wildlife within were venerated and given total protection."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s153", "tokens": [{"t": "text", "v": "Such sacred groves are found in "}, {"t": "cloze", "v": "Khasi and Jaintia Hills in Meghalaya"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "Aravalli Hills of Rajasthan"}, {"t": "text", "v": ", Western Ghat regions of Karnataka and Maharashtra and the Sarguja, Chanda and Bastar areas of Madhya Pradesh."}], "blanks": ["Khasi and Jaintia Hills in Meghalaya", "Aravalli Hills of Rajasthan"], "text": "Such sacred groves are found in Khasi and Jaintia Hills in Meghalaya, Aravalli Hills of Rajasthan, Western Ghat regions of Karnataka and Maharashtra and the Sarguja, Chanda and Bastar areas of Madhya Pradesh."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s154", "tokens": [{"t": "text", "v": "In "}, {"t": "cloze", "v": "Meghalaya"}, {"t": "text", "v": ", the "}, {"t": "cloze", "v": "sacred groves"}, {"t": "text", "v": " are the last refuges for a large number of rare and threatened plants."}], "blanks": ["Meghalaya", "sacred groves"], "text": "In Meghalaya, the sacred groves are the last refuges for a large number of rare and threatened plants."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s155", "tokens": [{"t": "cloze", "v": "Ex situ Conservation"}, {"t": "text", "v": " – In this approach, threatened animals and plants are taken out from their natural habitat and placed in special setting where they can be protected and given special care."}], "blanks": ["Ex situ Conservation"], "text": "Ex situ Conservation – In this approach, threatened animals and plants are taken out from their natural habitat and placed in special setting where they can be protected and given special care."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s156", "tokens": [{"t": "cloze", "v": "Zoological parks, botanical gardens and wildlife safari parks"}, {"t": "text", "v": " serve this purpose."}], "blanks": ["Zoological parks, botanical gardens and wildlife safari parks"], "text": "Zoological parks, botanical gardens and wildlife safari parks serve this purpose."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s157", "tokens": [{"t": "text", "v": "There are many animals that have become extinct in the wild but continue to be maintained in zoological parks."}], "blanks": [], "text": "There are many animals that have become extinct in the wild but continue to be maintained in zoological parks."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s158", "tokens": [{"t": "text", "v": "In recent years "}, {"t": "cloze", "v": "ex situ conservation"}, {"t": "text", "v": " has advanced beyond keeping threatened species in enclosures."}], "blanks": ["ex situ conservation"], "text": "In recent years ex situ conservation has advanced beyond keeping threatened species in enclosures."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s159", "tokens": [{"t": "text", "v": "Now gametes of threatened species can be preserved in viable and fertile condition for long periods using "}, {"t": "cloze", "v": "cryopreservation"}, {"t": "text", "v": " techniques, eggs can be fertilised "}, {"t": "cloze", "v": "in vitro"}, {"t": "text", "v": " , and plants can be propagated using tissue culture methods."}], "blanks": ["cryopreservation", "in vitro"], "text": "Now gametes of threatened species can be preserved in viable and fertile condition for long periods using cryopreservation techniques, eggs can be fertilised in vitro , and plants can be propagated using tissue culture methods."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s160", "tokens": [{"t": "text", "v": "Seeds of different genetic strains of commercially important plants can be kept for long periods in "}, {"t": "cloze", "v": "seed banks"}, {"t": "text", "v": "."}], "blanks": ["seed banks"], "text": "Seeds of different genetic strains of commercially important plants can be kept for long periods in seed banks."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s161", "tokens": [{"t": "text", "v": "Biodiversity knows no political boundaries and its conservation is therefore a collective responsibility of all nations."}], "blanks": [], "text": "Biodiversity knows no political boundaries and its conservation is therefore a collective responsibility of all nations."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s162", "tokens": [{"t": "text", "v": "The historic Convention on Biological Diversity (‘"}, {"t": "cloze", "v": "The Earth Summit"}, {"t": "text", "v": "’) held in "}, {"t": "cloze", "v": "Rio de Janeiro in 1992"}, {"t": "text", "v": ", called upon all nations to take appropriate measures for conservation of biodiversity and sustainable utilisation of its benefits."}], "blanks": ["The Earth Summit", "Rio de Janeiro in 1992"], "text": "The historic Convention on Biological Diversity (‘The Earth Summit’) held in Rio de Janeiro in 1992, called upon all nations to take appropriate measures for conservation of biodiversity and sustainable utilisation of its benefits."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s163", "tokens": [{"t": "text", "v": "In a follow-up, the "}, {"t": "cloze", "v": "World Summit on Sustainable Development"}, {"t": "text", "v": " held in 2002 in "}, {"t": "cloze", "v": "Johannesburg, South Africa"}, {"t": "text", "v": ", 190 countries pledged their commitment to achieve by 2010, a significant reduction in the current rate of biodiversity loss at global, regional and local levels."}], "blanks": ["World Summit on Sustainable Development", "Johannesburg, South Africa"], "text": "In a follow-up, the World Summit on Sustainable Development held in 2002 in Johannesburg, South Africa, 190 countries pledged their commitment to achieve by 2010, a significant reduction in the current rate of biodiversity loss at global, regional and local levels."}, {"type": "caption", "content": "Summary"}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s164", "tokens": [{"t": "text", "v": "Since life originated on earth nearly "}, {"t": "cloze", "v": "3.8 billion years ago"}, {"t": "text", "v": ", there had been enormous diversification of life forms on earth."}], "blanks": ["3.8 billion years ago"], "text": "Since life originated on earth nearly 3.8 billion years ago, there had been enormous diversification of life forms on earth."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s165", "tokens": [{"t": "text", "v": "Biodiversity refers to the sum total of diversity that exists at all levels of biological organisation."}], "blanks": [], "text": "Biodiversity refers to the sum total of diversity that exists at all levels of biological organisation."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s166", "tokens": [{"t": "text", "v": "Of particular importance is the diversity at "}, {"t": "cloze", "v": "genetic, species and ecosystem levels"}, {"t": "text", "v": " and conservation efforts are aimed at protecting diversity at all these levels."}], "blanks": ["genetic, species and ecosystem levels"], "text": "Of particular importance is the diversity at genetic, species and ecosystem levels and conservation efforts are aimed at protecting diversity at all these levels."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s167", "tokens": [{"t": "text", "v": "More than 1.5 million species have been recorded in the world, but there might still be "}, {"t": "cloze", "v": "nearly 6 million species"}, {"t": "text", "v": " on earth waiting to be discovered and named."}], "blanks": ["nearly 6 million species"], "text": "More than 1.5 million species have been recorded in the world, but there might still be nearly 6 million species on earth waiting to be discovered and named."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s168", "tokens": [{"t": "text", "v": "Of the named species, "}, {"t": "cloze", "v": "> 70 per cent are animals"}, {"t": "text", "v": ", of which "}, {"t": "cloze", "v": "70 per cent are insects"}, {"t": "text", "v": "."}], "blanks": ["> 70 per cent are animals", "70 per cent are insects"], "text": "Of the named species, > 70 per cent are animals, of which 70 per cent are insects."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s169", "tokens": [{"t": "text", "v": "The group "}, {"t": "cloze", "v": "Fungi"}, {"t": "text", "v": " has more species than all the vertebrate species combined."}], "blanks": ["Fungi"], "text": "The group Fungi has more species than all the vertebrate species combined."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s170", "tokens": [{"t": "text", "v": "India, with about "}, {"t": "cloze", "v": "45,000 species of plants"}, {"t": "text", "v": " and twice as many species of animals, is one of the "}, {"t": "cloze", "v": "12 mega diversity countries"}, {"t": "text", "v": " of the world."}], "blanks": ["45,000 species of plants", "12 mega diversity countries"], "text": "India, with about 45,000 species of plants and twice as many species of animals, is one of the 12 mega diversity countries of the world."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s171", "tokens": [{"t": "text", "v": "Species diversity on earth is not uniformly distributed but shows interesting patterns."}], "blanks": [], "text": "Species diversity on earth is not uniformly distributed but shows interesting patterns."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s172", "tokens": [{"t": "text", "v": "It is generally "}, {"t": "cloze", "v": "highest in the tropics"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "decreases towards the poles"}, {"t": "text", "v": "."}], "blanks": ["highest in the tropics", "decreases towards the poles"], "text": "It is generally highest in the tropics and decreases towards the poles."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s173", "tokens": [{"t": "text", "v": "Important explanations for the species richness of the tropics are: Tropics had "}, {"t": "cloze", "v": "more evolutionary time"}, {"t": "text", "v": "; they provide a relatively "}, {"t": "cloze", "v": "constant environment"}, {"t": "text", "v": " and, they receive more solar energy which contributes to greater productivity."}], "blanks": ["more evolutionary time", "constant environment"], "text": "Important explanations for the species richness of the tropics are: Tropics had more evolutionary time; they provide a relatively constant environment and, they receive more solar energy which contributes to greater productivity."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s174", "tokens": [{"t": "text", "v": "Species richness is also function of the area of a region; the "}, {"t": "cloze", "v": "species-area relationship"}, {"t": "text", "v": " is generally a "}, {"t": "cloze", "v": "rectangular hyperbolic function"}, {"t": "text", "v": "."}], "blanks": ["species-area relationship", "rectangular hyperbolic function"], "text": "Species richness is also function of the area of a region; the species-area relationship is generally a rectangular hyperbolic function."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s175", "tokens": [{"t": "text", "v": "It is believed that communities with high diversity tend to be less variable, more productive and more resistant to biological invasions."}], "blanks": [], "text": "It is believed that communities with high diversity tend to be less variable, more productive and more resistant to biological invasions."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s176", "tokens": [{"t": "text", "v": "Earth’s fossil history reveals incidence of mass extinctions in the past, but the present rates of extinction, largely attributed to human activities, are "}, {"t": "cloze", "v": "100 to 1000 times"}, {"t": "text", "v": " higher."}], "blanks": ["100 to 1000 times"], "text": "Earth’s fossil history reveals incidence of mass extinctions in the past, but the present rates of extinction, largely attributed to human activities, are 100 to 1000 times higher."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s177", "tokens": [{"t": "text", "v": "Nearly "}, {"t": "cloze", "v": "700 species"}, {"t": "text", "v": " have become extinct in recent times and more than "}, {"t": "cloze", "v": "15,500 species"}, {"t": "text", "v": " (of which > 650 are from India) currently face the threat of extinction."}], "blanks": ["700 species", "15,500 species"], "text": "Nearly 700 species have become extinct in recent times and more than 15,500 species (of which > 650 are from India) currently face the threat of extinction."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s178", "tokens": [{"t": "text", "v": "The causes of high extinction rates at present include "}, {"t": "cloze", "v": "habitat (particularly forests) loss and fragmentation"}, {"t": "text", "v": ", over-exploitation, biological invasions and "}, {"t": "cloze", "v": "co- extinctions"}, {"t": "text", "v": "."}], "blanks": ["habitat (particularly forests) loss and fragmentation", "co- extinctions"], "text": "The causes of high extinction rates at present include habitat (particularly forests) loss and fragmentation, over-exploitation, biological invasions and co- extinctions."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s179", "tokens": [{"t": "text", "v": "Earth’s rich biodiversity is vital for the very survival of mankind."}], "blanks": [], "text": "Earth’s rich biodiversity is vital for the very survival of mankind."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s180", "tokens": [{"t": "text", "v": "The reasons for conserving biodiversity are "}, {"t": "cloze", "v": "narrowly utilitarian, broadly utilitarian and ethical"}, {"t": "text", "v": ". Besides the direct benefits (food, fibre, firewood, pharmaceuticals, etc.), there are many indirect benefits we receive through ecosystem services such as pollination, pest control, climate moderation and flood control."}], "blanks": ["narrowly utilitarian, broadly utilitarian and ethical"], "text": "The reasons for conserving biodiversity are narrowly utilitarian, broadly utilitarian and ethical. Besides the direct benefits (food, fibre, firewood, pharmaceuticals, etc.), there are many indirect benefits we receive through ecosystem services such as pollination, pest control, climate moderation and flood control."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s181", "tokens": [{"t": "text", "v": "We also have a moral responsibility to take good care of earth’s biodiversity and pass it on in good order to our next generation."}], "blanks": [], "text": "We also have a moral responsibility to take good care of earth’s biodiversity and pass it on in good order to our next generation."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s182", "tokens": [{"t": "text", "v": "Biodiversity conservation may be "}, {"t": "cloze", "v": "in situ"}, {"t": "text", "v": " as well as "}, {"t": "cloze", "v": "ex situ"}, {"t": "text", "v": "."}], "blanks": ["in situ", "ex situ"], "text": "Biodiversity conservation may be in situ as well as ex situ."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s183", "tokens": [{"t": "text", "v": "In "}, {"t": "cloze", "v": "in situ conservation"}, {"t": "text", "v": ", the endangered species are protected in their "}, {"t": "cloze", "v": "natural habitat"}, {"t": "text", "v": " so that the entire ecosystem is protected."}], "blanks": ["in situ conservation", "natural habitat"], "text": "In in situ conservation, the endangered species are protected in their natural habitat so that the entire ecosystem is protected."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s184", "tokens": [{"t": "text", "v": "Recently, 34 "}, {"t": "cloze", "v": "‘biodiversity hotspots’"}, {"t": "text", "v": " in the world have been proposed for intensive conservation efforts."}], "blanks": ["‘biodiversity hotspots’"], "text": "Recently, 34 ‘biodiversity hotspots’ in the world have been proposed for intensive conservation efforts."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s185", "tokens": [{"t": "text", "v": "Of these, three ("}, {"t": "cloze", "v": "Western Ghats-Sri Lanka, Himalaya and Indo-Burma"}, {"t": "text", "v": ") cover India’s rich biodiversity regions."}], "blanks": ["Western Ghats-Sri Lanka, Himalaya and Indo-Burma"], "text": "Of these, three (Western Ghats-Sri Lanka, Himalaya and Indo-Burma) cover India’s rich biodiversity regions."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s186", "tokens": [{"t": "text", "v": "Our country’s in situ conservation efforts are reflected in its "}, {"t": "cloze", "v": "14 biosphere reserves, 90 national parks, > 450 wildlife sanctuaries"}, {"t": "text", "v": " and many "}, {"t": "cloze", "v": "sacred groves"}, {"t": "text", "v": "."}], "blanks": ["14 biosphere reserves, 90 national parks, > 450 wildlife sanctuaries", "sacred groves"], "text": "Our country’s in situ conservation efforts are reflected in its 14 biosphere reserves, 90 national parks, > 450 wildlife sanctuaries and many sacred groves."}, {"type": "sentence", "id": "Biodiversity_and_Conservation_s187", "tokens": [{"t": "cloze", "v": "Ex situ conservation"}, {"t": "text", "v": " methods include protective maintenance of threatened species in zoological parks and botanical gardens, in vitro fertilisation, tissue culture propagation and "}, {"t": "cloze", "v": "cryopreservation"}, {"t": "text", "v": " of gametes."}], "blanks": ["Ex situ conservation", "cryopreservation"], "text": "Ex situ conservation methods include protective maintenance of threatened species in zoological parks and botanical gardens, in vitro fertilisation, tissue culture propagation and cryopreservation of gametes."}]};
